import numpy as np


def mel_points(f_min, f_max, n):
    def to_mel(f):
        return 2595 * np.log10(1 + f / 700)

    def to_hz(m):
        return 700 * (10 ** (m / 2595) - 1)

    return to_hz(np.linspace(to_mel(f_min), to_mel(f_max), n + 2))
